def backfill_overdue_as_reminded(apps, schema_editor):
    """
    Mark every PENDING task that is already due as "reminder sent", so the first run of
    send_task_reminders does not push a backlog of old follow-ups to everyone.
    Uses a queryset update (no save()/signals). Returns the number of rows updated.
    """
    Task = apps.get_model('crm', 'Task')
    now = timezone.now()
    return Task.objects.filter(
        status='PENDING',
        due_date__lte=now,
        reminder_sent_at__isnull=True,
    ).update(reminder_sent_at=now)


